<?php if(post_password_required())return; ?><section id="comments" class="comments-area"><?php if(have_comments()): ?><h2><?php printf(esc_html(_n('%s comentário','%s comentários',get_comments_number(),'gamezone')),number_format_i18n(get_comments_number())); ?></h2><ol class="comment-list"><?php wp_list_comments(array('style'=>'ol','short_ping'=>true)); ?></ol><?php the_comments_pagination();endif;if(!comments_open()&&get_comments_number())echo '<p>'.esc_html__('Comentários encerrados.','gamezone').'</p>';comment_form(); ?></section>